// 新独立段的JSON/二进制坏档与字段序门；不把结构门当完整World来源验收。
#include "resident/domains/growth/growth_market_history_codec.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <algorithm>
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}}
int main(){try{
    Owner owner{Owner::Kind::household,"market_household",{}, {}};LotView before{"lot:1","millet",{},12,owner,{}},after=before;after.quantity=7;
    MarketMovementRecord record;record.business_fact_id="action:3";record.steps.push_back({MarketCaptureStage::trade,4,4,{{"market",0,1,{{"lot:1",before,after}}}}});GrowthMarketHistoryState state;state.movements.insert("market_history:5",record);
    auto json=encode_growth_market_history(state);auto read=decode_growth_market_history(json);check(read.ok&&compare_boundary(json,encode_growth_market_history(read.value)).exact(),"JSON typed fields exact");auto reordered=json;std::reverse(reordered.as<BoundaryValue::Dict>()->begin(),reordered.as<BoundaryValue::Dict>()->end());read=decode_growth_market_history(reordered);check(read.ok&&compare_boundary(reordered,encode_growth_market_history(read.value)).exact(),"root insertion order preserved");
    CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto binary=state;check(visit_growth_market_history_checkpoint(writer,binary).ok&&writer.finish().ok,"typed binary write without another domain feature bit");check(writer.schema_features==0,"owner codec leaves caller flags unchanged");GrowthMarketHistoryState restored;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));check(visit_growth_market_history_checkpoint(reader,restored).ok&&reader.finish().ok&&compare_boundary(json,encode_growth_market_history(restored)).exact(),"binary typed restore exact");auto broken=bytes;broken.pop_back();CodecVisitor truncated(static_cast<const CodecVisitor::Buffer&>(broken));check(!visit_growth_market_history_checkpoint(truncated,restored).ok||!truncated.finish().ok,"truncated record rejects");
    auto duplicate=json;duplicate.as<BoundaryValue::Dict>()->push_back(duplicate.as<BoundaryValue::Dict>()->front());check(!decode_growth_market_history(duplicate).ok,"duplicate root key rejects");duplicate=json;auto* movement=duplicate.find("movements")->find("market_history:5");movement->as<BoundaryValue::Dict>()->emplace_back("source_tick",BoundaryValue{Integer{0}});check(!decode_growth_market_history(duplicate).ok,"duplicate record key rejects");duplicate=json;auto* lot=duplicate.find("movements")->find("market_history:5")->find("steps")->as<BoundaryValue::Array>()->front().find("inventories")->as<BoundaryValue::Array>()->front().find("lots")->as<BoundaryValue::Array>()->front().find("before");lot->find("owner")->as<BoundaryValue::Dict>()->emplace_back("id",BoundaryValue{StableId{"market_household"}});check(!decode_growth_market_history(duplicate).ok,"nested Owner duplicate rejects before first-match");
    auto bad=state;bad.movements.find("market_history:5")->business_kind=static_cast<MarketCauseKind>(9);check(!validate_growth_market_history_shape(bad).ok,"unknown business enum rejects");bad=state;bad.movements.find("market_history:5")->steps[0].inventories[0].lots[0].after->reserved_by="action:8";check(!validate_growth_market_history_shape(bad).ok,"reservation mutation cannot hide in frozen lot");bad=state;bad.movements.find("market_history:5")->steps[0].inventories[0].lots[0].after->quantity=12;check(!validate_growth_market_history_shape(bad).ok,"no-change receipt rejected");
    std::cout<<"GROWTH_MARKET_CODEC "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_MARKET_CODEC "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
